#!/usr/bin/env python3
"""Compute ground truth for CSX-067_Q1."""

from __future__ import annotations

import html
import json
import re
import unicodedata
from datetime import date
from pathlib import Path
from typing import Any


TASK_ID = "CSX-067_Q1"
EVENT_ID = "CSX-067"

TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

METADATA_FILE = "metadata/event.json"
ANCHOR_REPORT = "data/event_reports/event_reports_004_Locked_event_anchor_2023_Sao_Sebastiao_floods_and_landslides.json"
EVIDENCE_REPORT = "data/event_reports/event_reports_005_01_Locked_package_evidence_report.html.html"

SOURCE_FILES = [
    METADATA_FILE,
    ANCHOR_REPORT,
    EVIDENCE_REPORT,
]


def read_json(rel_path: str) -> dict[str, Any]:
    with (PACKAGE_DIR / rel_path).open("r", encoding="utf-8-sig", errors="replace") as handle:
        return json.load(handle)


def read_text(rel_path: str) -> str:
    return (PACKAGE_DIR / rel_path).read_text(encoding="utf-8", errors="replace")


def ascii_text(value: str) -> str:
    normalized = unicodedata.normalize("NFKD", value)
    return normalized.encode("ascii", "ignore").decode("ascii")


def plain_text_from_html(raw_html: str) -> str:
    raw_html = re.sub(r"<script\b.*?</script>", " ", raw_html, flags=re.IGNORECASE | re.DOTALL)
    raw_html = re.sub(r"<style\b.*?</style>", " ", raw_html, flags=re.IGNORECASE | re.DOTALL)
    text = html.unescape(re.sub(r"<[^>]+>", " ", raw_html))
    return re.sub(r"\s+", " ", ascii_text(text)).strip()


def parse_iso(value: str) -> date:
    year, month, day = (int(part) for part in value.split("-"))
    return date(year, month, day)


def extract_report_values(raw_html: str) -> dict[str, Any]:
    text = plain_text_from_html(raw_html)
    rainfall_match = re.search(r"more than\s+([0-9]+)\s+millimeters", text, flags=re.IGNORECASE)
    if not rainfall_match:
        raise ValueError("Could not extract rainfall lower-bound statement")
    if "On February 19, 2023" not in text:
        raise ValueError("Could not confirm February 19, 2023 rainfall trigger")
    for image_date in ("October 29, 2022", "February 26, 2023"):
        if image_date not in text:
            raise ValueError(f"Could not confirm report image date: {image_date}")
    return {
        "rain_trigger_iso": "2023-02-19",
        "rainfall_mm_lower_bound": int(rainfall_match.group(1)),
        "pre_image_iso": "2022-10-29",
        "post_image_iso": "2023-02-26",
    }


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "final_ledger_state",
                "points": 4,
                "description": "Gives compound_rainfall_saturation_pass and pass_count = 4.",
                "partial_credit": "Award 2 points for the combined rainfall-saturation outcome without the pass count, or 1 point for a vague heavy-rain label without the ledger state.",
            },
            {
                "name": "extracted_event_anchors",
                "points": 4,
                "description": "Reports 680 mm, 2023-02-18 to 2023-02-21, 2023-02-19, and 2023-02-26 correctly.",
                "partial_credit": "Award 1 point for each correct anchor; give no credit for replacing the lower bound with unrelated gridded values.",
            },
            {
                "name": "rainfall_formula_values",
                "points": 4,
                "description": "Computes 4 inclusive days, 170.0 mm/day, and 1.36 threshold multiple with correct units or field names.",
                "partial_credit": "Award 2 points if only one derived rainfall value is correct, or 1 point if formulas are stated but arithmetic is wrong.",
            },
            {
                "name": "post_image_timing_logic",
                "points": 3,
                "description": "Computes the 7-day post-image lag and applies the <= 10 days threshold.",
                "partial_credit": "Award 1.5 points for the correct lag without the threshold result, or 1 point for recognizing post-storm timing with the wrong day count.",
            },
            {
                "name": "threshold_check_application",
                "points": 3,
                "description": "Evaluates all four ledger checks using the specified inequalities.",
                "partial_credit": "Award 0.75 point for each correctly evaluated check.",
            },
            {
                "name": "compact_interpretation_and_json",
                "points": 2,
                "description": "Returns valid compact JSON and keeps the interpretation tied to the computed rainfall and timing ledger.",
                "partial_credit": "Award 1 point if the JSON is mostly usable but verbose, or if the interpretation is plausible but not clearly tied to the computed checks.",
            },
        ],
    }


def main() -> None:
    metadata = read_json(METADATA_FILE)
    anchor = read_json(ANCHOR_REPORT)
    report = extract_report_values(read_text(EVIDENCE_REPORT))

    if metadata.get("package_id") != EVENT_ID or anchor.get("package_id") != EVENT_ID:
        raise ValueError("Package metadata does not match CSX-067")

    start_iso = anchor["temporal_window"]["start_date"]
    end_iso = anchor["temporal_window"]["end_date"]
    event_window_days = (parse_iso(end_iso) - parse_iso(start_iso)).days + 1
    rainfall_mm = report["rainfall_mm_lower_bound"]
    window_mean = round(rainfall_mm / event_window_days, 1)
    rainfall_threshold_multiple = round(rainfall_mm / 500, 2)
    post_image_lag_days = (parse_iso(report["post_image_iso"]) - parse_iso(report["rain_trigger_iso"])).days

    checks = {
        "extreme_rain": rainfall_mm >= 500,
        "compact_event_window": event_window_days <= 4,
        "high_lower_bound_window_mean": window_mean >= 100,
        "timely_aftermath_image": post_image_lag_days <= 10,
    }
    pass_count = sum(1 for passed in checks.values() if passed)
    answer = "compound_rainfall_saturation_pass" if pass_count == len(checks) else "ledger_not_fully_met"

    primary_gt = {
        "answer": answer,
        "rainfall_mm_lower_bound": rainfall_mm,
        "event_window_days": event_window_days,
        "window_mean_lower_bound_mm_per_day": window_mean,
        "rainfall_threshold_multiple": rainfall_threshold_multiple,
        "post_image_lag_days": post_image_lag_days,
        "pass_count": pass_count,
        "interpretation": "The conservative ledger supports a rainfall-saturation slope-failure and flash-flood diagnosis for Sao Sebastiao.",
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "threshold_ledger",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": metadata["event_name"],
            "location": anchor["spatial_window"]["location_text"],
            "country_or_region": anchor["spatial_window"]["country_or_region"],
            "event_start": start_iso,
            "event_end": end_iso,
            "rain_trigger": report["rain_trigger_iso"],
            "pre_image_date": report["pre_image_iso"],
            "post_image_date": report["post_image_iso"],
            "thresholds": {
                "extreme_rain_mm": 500,
                "max_compact_window_days": 4,
                "min_window_mean_mm_per_day": 100,
                "max_post_image_lag_days": 10,
            },
            "checks": checks,
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "Ground truth is generated from the locked event dates and the report rainfall and image-date statements.",
        },
    }

    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(output, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
